package com.mariam.live
import android.app.Activity
import android.os.Bundle
import android.graphics.Color
import android.graphics.drawable.GradientDrawable
import android.view.Gravity
import android.widget.*
import org.json.JSONArray
import org.json.JSONObject
import kotlin.concurrent.thread

class AgencyEarningsActivity:Activity(){
 private val bg=Color.rgb(12,10,20);private val panel=Color.rgb(29,22,40);private val muted=Color.rgb(169,157,185);private val accent=Color.rgb(120,226,181)
 private lateinit var body:LinearLayout;private var token="";private var overview=JSONObject();private var members=JSONArray();private var history=JSONArray()
 private fun dp(v:Int)=(v*resources.displayMetrics.density).toInt()
 private fun money(c:Long)=String.format(java.util.Locale.US,"$%.2f",c/100.0)
 private fun card()=GradientDrawable(GradientDrawable.Orientation.TL_BR,intArrayOf(Color.rgb(42,31,55),panel)).apply{cornerRadius=dp(16).toFloat();setStroke(dp(1),Color.rgb(76,57,92))}
 private fun t(s:String,z:Float,c:Int=Color.WHITE,b:Boolean=false)=TextView(this).apply{text=s;textSize=z;setTextColor(c);if(b)typeface=android.graphics.Typeface.DEFAULT_BOLD}
 private fun section(s:String,sub:String=""){body.addView(t(s,17f,Color.WHITE,true),LinearLayout.LayoutParams(-1,-2).apply{topMargin=dp(20);bottomMargin=dp(5)});if(sub.isNotBlank())body.addView(t(sub,11f,muted))}
 private fun stat(title:String,value:String,icon:String):LinearLayout{val x=LinearLayout(this);x.orientation=1;x.gravity=Gravity.CENTER;x.setPadding(dp(10),dp(14),dp(10),dp(14));x.background=card();x.addView(t(icon,22f,accent,true));x.addView(t(title,11f,muted,true),LinearLayout.LayoutParams(-1,-2).apply{topMargin=dp(4)});x.addView(t(value,18f,Color.WHITE,true),LinearLayout.LayoutParams(-1,-2).apply{topMargin=dp(6)});return x}
 override fun onCreate(savedInstanceState:Bundle?){super.onCreate(savedInstanceState);token=getSharedPreferences("MariamLive",MODE_PRIVATE).getString("token","").orEmpty();window.statusBarColor=bg;window.navigationBarColor=bg
 val root=LinearLayout(this);root.orientation=1;root.setBackgroundColor(bg);val header=LinearLayout(this);header.gravity=Gravity.CENTER_VERTICAL;header.setPadding(dp(16),dp(8),dp(16),dp(8))
 header.addView(t("‹",32f).apply{gravity=Gravity.CENTER;setOnClickListener{finish()}},LinearLayout.LayoutParams(dp(42),dp(48)));header.addView(t("أرباح الوكالة",19f,Color.WHITE,true).apply{gravity=Gravity.CENTER},LinearLayout.LayoutParams(0,dp(48),1f));header.addView(t("BAK",12f,accent,true));root.addView(header)
 val sc=ScrollView(this);body=LinearLayout(this);body.orientation=1;body.setPadding(dp(16),dp(8),dp(16),dp(28));sc.addView(body);root.addView(sc,LinearLayout.LayoutParams(-1,0,1f));setContentView(root);load()}
 private fun load(){body.removeAllViews();body.addView(t("جارٍ تحميل الأرباح...",13f,muted));if(token.isBlank()){err("يرجى تسجيل الدخول مجدداً");return}
 thread{try{val a=AuthApi.get("/api/agency/earnings",token);val b=AuthApi.get("/api/agency/earnings/members",token);val c=AuthApi.get("/api/agency/earnings/history",token);if(a.status !in 200..299)throw Exception(a.body.optString("error","تعذر تحميل الملخص"));if(b.status !in 200..299)throw Exception(b.body.optString("error","تعذر تحميل الأعضاء"));if(c.status !in 200..299)throw Exception(c.body.optString("error","تعذر تحميل السجل"));val ov=a.body.optJSONObject("earnings")?:a.body.optJSONObject("overview")?:a.body;val mm=b.body.optJSONArray("members")?:JSONArray();val hh=c.body.optJSONArray("history")?:c.body.optJSONArray("earnings")?:JSONArray();runOnUiThread{overview=ov;members=mm;history=hh;render()}}catch(e:Exception){runOnUiThread{err(e.message?: "تعذر الاتصال بالخادم")}}}}
 private fun err(s:String){body.removeAllViews();body.addView(t(s,14f));val retry=t("إعادة المحاولة",14f,Color.WHITE,true);retry.gravity=Gravity.CENTER;retry.setPadding(dp(14),dp(14),dp(14),dp(14));retry.background=card();retry.setOnClickListener{load()};body.addView(retry,LinearLayout.LayoutParams(-1,-2).apply{topMargin=dp(12)})}
 private fun v(vararg keys:String):Long{for(k in keys)if(overview.has(k)&&!overview.isNull(k))return overview.optLong(k,0);return 0}
 private fun render(){body.removeAllViews();val hero=LinearLayout(this);hero.orientation=1;hero.setPadding(dp(18),dp(20),dp(18),dp(20));hero.background=GradientDrawable(GradientDrawable.Orientation.TL_BR,intArrayOf(Color.rgb(105,44,150),Color.rgb(34,22,52))).apply{cornerRadius=dp(22).toFloat()}
 hero.addView(t("BAK LIVE • AGENCY PARTNER",10f,Color.rgb(226,205,244),true));hero.addView(t("إجمالي أرباح الوكالة",15f,Color.WHITE,true),LinearLayout.LayoutParams(-1,-2).apply{topMargin=dp(10)});hero.addView(t(money(v("total_cents","total_earnings_cents","total_usd_cents")),34f,accent,true),LinearLayout.LayoutParams(-1,-2).apply{topMargin=dp(5)});hero.addView(t("عمولة الوكالة 12% من هدايا الأعضاء المؤهلين",12f,Color.rgb(232,214,245)),LinearLayout.LayoutParams(-1,-2).apply{topMargin=dp(7)});body.addView(hero)
 val one=LinearLayout(this);one.orientation=0;one.addView(stat("المتاح",money(v("available_cents","available_earnings_cents")),"💰"),LinearLayout.LayoutParams(0,-2,1f).apply{marginEnd=dp(5)});one.addView(stat("المدفوع",money(v("paid_cents","paid_earnings_cents")),"✓"),LinearLayout.LayoutParams(0,-2,1f).apply{marginStart=dp(5)});body.addView(one,LinearLayout.LayoutParams(-1,-2).apply{topMargin=dp(10)})
 val two=LinearLayout(this);two.orientation=0;two.addView(stat("اليوم",money(v("today_cents","today_earnings_cents")),"☀"),LinearLayout.LayoutParams(0,-2,1f).apply{marginEnd=dp(5)});two.addView(stat("7 أيام",money(v("last_7_days_cents","week_cents")),"↗"),LinearLayout.LayoutParams(0,-2,1f).apply{marginStart=dp(5)});body.addView(two,LinearLayout.LayoutParams(-1,-2).apply{topMargin=dp(10)});body.addView(stat("هذا الشهر",money(v("month_cents","monthly_cents","month_earnings_cents")),"▣"),LinearLayout.LayoutParams(-1,-2).apply{topMargin=dp(10)})
 section("أعضاء الوكالة","ترتيب حسب إجمالي أرباح العضو");if(members.length()==0)body.addView(t("لا توجد أرباح مسجلة للأعضاء حتى الآن",12f,muted).apply{setPadding(dp(12),dp(18),dp(12),dp(18))})
 for(i in 0 until members.length()){val o=members.optJSONObject(i)?:continue;val name=o.optString("display_name").ifBlank{o.optString("username").ifBlank{"ID "+o.optString("public_id","—")}};val total=o.optLong("total_cents",o.optLong("total_earnings_cents",0));val avail=o.optLong("available_cents",0);val row=LinearLayout(this);row.orientation=1;row.setPadding(dp(14),dp(13),dp(14),dp(13));row.background=card();row.addView(t(name,14f,Color.WHITE,true));row.addView(t("إجمالي "+money(total)+" • متاح "+money(avail),12f,muted),LinearLayout.LayoutParams(-1,-2).apply{topMargin=dp(5)});body.addView(row,LinearLayout.LayoutParams(-1,-2).apply{bottomMargin=dp(7)})}
 section("سجل العمولات","عمولات الهدايا الجديدة فقط");if(history.length()==0)body.addView(t("لا توجد عمليات أرباح بعد",12f,muted).apply{setPadding(dp(12),dp(18),dp(12),dp(18))})
 for(i in 0 until history.length()){val o=history.optJSONObject(i)?:continue;val who=o.optString("display_name").ifBlank{o.optString("username").ifBlank{"عضو الوكالة"}};val gift=o.optString("gift_id").ifBlank{"هدية"};val amount=o.optLong("amount_cents",o.optLong("amount",0));val date=o.optString("created_at","");val row=LinearLayout(this);row.orientation=0;row.gravity=Gravity.CENTER_VERTICAL;row.setPadding(dp(13),dp(12),dp(13),dp(12));row.background=card();val info=LinearLayout(this);info.orientation=1;info.addView(t(who+" • "+gift,13f,Color.WHITE,true));if(date.isNotBlank())info.addView(t(date,10f,muted),LinearLayout.LayoutParams(-1,-2).apply{topMargin=dp(4)});row.addView(info,LinearLayout.LayoutParams(0,-2,1f));row.addView(t("+"+money(amount),15f,accent,true));body.addView(row,LinearLayout.LayoutParams(-1,-2).apply{bottomMargin=dp(6)})}
 val refresh=t("تحديث البيانات",14f,Color.WHITE,true);refresh.gravity=Gravity.CENTER;refresh.setPadding(dp(14),dp(14),dp(14),dp(14));refresh.background=card();refresh.setOnClickListener{load()};body.addView(refresh,LinearLayout.LayoutParams(-1,-2).apply{topMargin=dp(16)})
 }
}
